import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:farmgenie_fresh_cart/models/workday.dart';
import 'package:farmgenie_fresh_cart/services/workday_controller.dart';
import 'package:farmgenie_fresh_cart/screens/attendance_screen.dart';
import 'package:farmgenie_fresh_cart/screens/request_screen.dart';
import 'package:farmgenie_fresh_cart/screens/splash_screen.dart';
import 'package:farmgenie_fresh_cart/theme/brand_theme.dart';
import 'widget_test.dart' show openLogin, login, tapVisible;

void main() {
  test('sample records classify dates and subtract breaks correctly', () {
    final workday = WorkdayController(today: DateTime(2026, 10, 20));
    expect(workday.record(workday.today).hoursLabel, '4h 28m');
    expect(workday.record(DateTime(2026, 10, 19)).hoursLabel, '8h 00m');
    expect(workday.record(DateTime(2026, 10, 14)).status, AttendanceStatus.absent);
    expect(workday.record(DateTime(2026, 10, 11)).status, AttendanceStatus.off);
    expect(workday.record(DateTime(2026, 10, 21)).status, AttendanceStatus.upcoming);
    workday.dispose();
  });

  testWidgets('splash completes between two and four seconds', (tester) async {
    var complete = false;
    await tester.pumpWidget(MaterialApp(home: SplashScreen(onComplete: () => complete = true)));
    await tester.pump(const Duration(seconds: 2));
    expect(complete, false);
    await tester.pump(const Duration(milliseconds: 900));
    expect(complete, true);
    await tester.pumpWidget(const SizedBox());
  });

  testWidgets('drawer opens modules and back returns home', (tester) async {
    await openLogin(tester); await login(tester);
    await tapVisible(tester, find.byTooltip('Open navigation menu'));
    await tapVisible(tester, find.widgetWithText(ListTile, 'Material Request'));
    expect(find.text('Material / item name'), findsOneWidget);
    await tester.binding.handlePopRoute();
    await tester.pumpAndSettle();
    expect(find.text('Your workday'), findsOneWidget);
    await tapVisible(tester, find.text('Attendance'));
    expect(find.text('Month overview'), findsOneWidget);
    await tester.pumpWidget(const SizedBox());
  });

  testWidgets('calendar handles leap month, selection and future days', (tester) async {
    final workday = WorkdayController(today: DateTime(2028, 3, 2));
    await tester.pumpWidget(MaterialApp(theme: Brand.theme, home: Scaffold(
      body: AttendanceScreen(workday: workday, onLeave: () {}))));
    await tester.pumpAndSettle();
    await tapVisible(tester, find.byTooltip('Previous month'));
    expect(find.text('February 2028'), findsOneWidget);
    await tapVisible(tester, find.byKey(ValueKey('day-${DateTime(2028, 2, 29).toIso8601String()}')));
    expect(find.text('Working hours: 8h 00m'), findsOneWidget);
    await tapVisible(tester, find.byTooltip('Next month'));
    await tapVisible(tester, find.byKey(ValueKey('day-${DateTime(2028, 3, 3).toIso8601String()}')));
    expect(find.text('No attendance is recorded for this future date.'), findsOneWidget);
    await tester.pumpWidget(const SizedBox()); workday.dispose();
  });

  testWidgets('material form validates and saves only a local demo request', (tester) async {
    final workday = WorkdayController(today: DateTime(2026, 10, 20));
    await tester.pumpWidget(MaterialApp(theme: Brand.theme, home: Scaffold(
      body: RequestScreen(workday: workday, leave: false))));
    await tapVisible(tester, find.text('Save demo request'));
    expect(find.text('This field is required.'), findsNWidgets(2));
    expect(find.text('Enter a whole number greater than zero.'), findsOneWidget);
    await tester.enterText(find.byType(TextFormField).at(0), 'Paper bags');
    await tester.enterText(find.byType(TextFormField).at(1), '25');
    await tester.enterText(find.byType(TextFormField).at(2), 'Checkout counter');
    await tapVisible(tester, find.text('Save demo request'));
    expect(workday.materials.single.title, 'Paper bags');
    expect(find.text('Demo only • Not submitted'), findsOneWidget);
    await tester.pumpWidget(const SizedBox()); workday.dispose();
  });

  testWidgets('leave form requires reason and date range', (tester) async {
    final workday = WorkdayController(today: DateTime(2026, 10, 20));
    await tester.pumpWidget(MaterialApp(theme: Brand.theme, home: Scaffold(
      body: RequestScreen(workday: workday, leave: true))));
    await tapVisible(tester, find.text('Save demo request'));
    expect(find.text('Select your leave dates.'), findsOneWidget);
    expect(find.text('This field is required.'), findsOneWidget);
    expect(workday.leaves, isEmpty);
    await tapVisible(tester, find.byKey(const ValueKey('leave-dates')));
    expect(find.byType(DateRangePickerDialog), findsOneWidget);
    await tester.binding.handlePopRoute();
    await tester.pumpAndSettle();
    expect(workday.leaves, isEmpty);
    await tester.pumpWidget(const SizedBox()); workday.dispose();
  });

  testWidgets('calendar and forms fit small screens at double text size', (tester) async {
    tester.view.physicalSize = const Size(320, 640);
    tester.view.devicePixelRatio = 1;
    tester.platformDispatcher.textScaleFactorTestValue = 2;
    addTearDown(() {
      tester.view.resetPhysicalSize(); tester.view.resetDevicePixelRatio();
      tester.platformDispatcher.clearTextScaleFactorTestValue();
    });
    final workday = WorkdayController(today: DateTime(2026, 10, 20));
    for (final screen in [
      AttendanceScreen(workday: workday, onLeave: () {}),
      RequestScreen(workday: workday, leave: true),
      RequestScreen(workday: workday, leave: false),
    ]) {
      await tester.pumpWidget(MaterialApp(theme: Brand.theme, home: Scaffold(body: screen)));
      await tester.pumpAndSettle();
      expect(tester.takeException(), isNull);
    }
    await tester.pumpWidget(const SizedBox()); workday.dispose();
  });
}
